from pathlib import Path
import re

p = Path(__file__).resolve().parent.parent / 'report_human_hackathon_strategy.md'
s = p.read_text(encoding='utf-8')

def table(marker, replacement):
    global s
    start = s.index('\n|', s.index(marker)) + 1
    end = s.find('\n\n', start)
    s = s[:start] + replacement.strip() + s[end:]

